INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('200819-varas-mena-san-miguel', 'Varas Mena / San Miguel', 'departamento', 'arriendo', 'San Miguel', '', 460000, 'CLP', 'mes', 2, 2, 1, 0, 60, 64, NULL, NULL, '', 0, NULL, '["Estacionamiento adicional"]', 'Se arrienda departamento ubicado en sector Centro de la comuna de San Miguel', '["Se arrienda departamento ubicado en sector Centro de la comuna de San Miguel\nExcelente ubicación, cercano a la estación del metro Ciudad del Niño, comercios y supermercados.\nEl departamento cuenta con 2 dormitorios, 2 baños, cocina independiente y terraza.\nEl departamento + bodega : $460.000\nDe departamento + bodega+ estacionamiento: $510.000\nDisponibilidad: 15 de septiembre (se pueden realizar visitas desde ahora)\nGasto común: Promedio $68.000\nReajuste: IPC anual\nComisión de corretaje: 50% de un mes de arriendo + IVA"]', '["Bodega", "Terraza", "Buena Conectividad", "Comercio Cercano"]', 0, '2026-11-12', 'PUBLICADA', 422, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201517-departamental-macul', 'Departamental / Macul', 'departamento', 'arriendo', 'Macul', '', 600000, 'CLP', 'mes', 2, 2, 1, 0, 55, 55, NULL, NULL, '', 0, NULL, '[]', 'Se arrienda hermoso y espacioso departamento ubicado en Av.', '["Se arrienda hermoso y espacioso departamento ubicado en Av. departamental frente a la clinica Bupa, cercano a metro Macul, comercios, supermercados, farmacias, restaurantes, con buena conexcion a transporte publico.\nCaracteristicas del departamento:\n-55 mt aprox. totales.\n-2 dormitorios (principal con salida a terraza y en suite)\n-2 baños completos.\n-Living comedor amplio con salida a terraza amplia.\n-Cocina americana semi equipada.\n-Orientacion Norte.\n-Excelente distribución.\n-Conexion a lavadora.\n-Piso 2.\n-2 Estacionamientos en tandem.\n-Bodega.\nGasto común $100.000 a $120.000\nCondominio cuenta con acceso controlado conserjería 24/7, quinchos, bicicleteros, salas de usos múltiples, lavandería y estacionamiento para visitas.\nAntecedentes solicitados para postular al arriendo:\n-Demostrar mínimo 3 veces líquido el valor de arriendo.\n-Fotocopia de cédula de identidad.\n-Informe comercial Dicom Equifax Platinum 360 (se obtiene vía internet).\n-Certificado AFP de las últimas 12 cotizaciones.\nPara el aval se solicitan los mismos antecedentes mencionados.\nSe solicita:\n-Mes de arriendo.\n-Mes y medio de garantía.\n-Comisión de corretaje 50% de un canon de arriendo.\n¡No deje de visitar!"]', '["Condominio", "Cocina Americana", "Bodega", "Terraza", "Quincho", "Buena Conectividad", "Comercio Cercano", "Centros de Salud", "Seguridad", "Wifi"]', 0, '2026-11-12', 'PUBLICADA', 123, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201520-oficina-diagonal-paraguay', 'Oficina / Diagonal Paraguay', 'oficina', 'arriendo', 'Santiago', '', 250000, 'CLP', 'mes', 0, 1, 0, 0, 30, 30, NULL, NULL, '', 0, NULL, '[]', '¿Buscas el espacio perfecto para consolidar tu empresa o atender a tus clientes en una ubicación estratégica?', '["¿Buscas el espacio perfecto para consolidar tu empresa o atender a tus clientes en una ubicación estratégica? Esta oficina en Diagonal Paraguay combina funcionalidad, seguridad y la mejor relación precio-calidad del sector.\n¿Por qué te va a encantar?\nDistribución eficiente: Planta con excelente iluminación y 2 divisiones ideales para privada/sala de reuniones y área de trabajo.\nExcelente primera impresión: Espacio para recepción independiente para recibir a tus clientes como se merecen.\nEdificio 100% corporativo: Entorno profesional, tranquilo y con seguridad/conserjería 24/7.\nUbicación privilegiada: A solo minutos a pie del Metro Santa Lucía, con accesibilidad inmejorable a servicios, bancos y restaurantes.\nDetalles de la propiedad:\nSuperficie: 30 m² aprox.\nDistribución: Recepción + 2 privados/divisiones + 1 baño privado.\nTerminaciones: Piso flotante de alto tráfico en excelente estado.\nCondiciones comerciales:\nCanon de arriendo: $250.000 / mes\nGastos comunes: $80.000 aprox.\nComisión corretaje: 50% + IVA del primer mes de arriendo.\n¡Haz crecer tu negocio desde hoy! Agenda tu visita y no dejes pasar esta oportunidad."]', '["Accesibilidad", "Buena Conectividad", "Seguridad", "2 privados"]', 0, '2026-11-12', 'PUBLICADA', 126, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201522-la-reina-alta-casa', 'La Reina Alta / Casa', 'casa', 'venta', 'La Reina', '', 16290, 'UF', NULL, 4, 4, 3, 0, 352, 352, 352, NULL, '', 0, NULL, '[]', 'Espectacular casa en exclusivo sector de La Reina Alta', '["Espectacular casa en exclusivo sector de La Reina Alta\nUbicada en uno de los sectores más residenciales y consolidados de La Reina Alta, esta propiedad de dos niveles destaca por sus amplios y luminosos espacios, ideales para la vida en familia. Su excelente conectividad la sitúa a solo 5 minutos del British Royal School y a 8 minutos del Colegio Andrée, cercana además a supermercados, farmacias y plazas.\nCaracterísticas Principales:\nSuperficie total: 352 m² aprox.\nOrientación: Nororiente (excelente iluminación natural)\nDormitorios: 4 (principal en suite con walk-in closet + servicio)\nBaños: 4 (incluye visitas y servicio)\nEstacionamiento: Capacidad para 3 vehículos\nOtros: Bodega, piscina y jardín formado\nGastos comunes: $120.000 aprox.\nDistribución de la Propiedad:\nPrimer Piso:\nHall de entrada.\nBaño de visitas.\nAmplio living-comedor independiente con salida directa a una gran terraza techada.\nCocina equipada con comedor de diario y cubiertas de Silestone.\nDormitorio de servicio completo (con baño).\nLoggia independiente.\nDormitorio principal en suite con walk-in closet.\nSegundo Piso:\nAcogedora sala de estar.\n2 dormitorios secundarios de gran tamaño.\n1 baño completo.\nEquipamiento y Terminations:\nVentanas de PVC con termopanel.\nCalefacción central por radiadores.\nJardín consolidado con sistema de riego automático.\nPiscina revestida en cuarzo."]', '["Residencial", "Walk-in Closet", "Bodega", "Piscina", "Terraza", "Áreas Verdes", "Riego Automático", "Buena Conectividad", "Comercio Cercano", "Colegio Cercano", "Calefacción"]', 0, '2026-11-12', 'PUBLICADA', 128, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201525-cipres-cordillerano-la-florida', 'Cipres Cordillerano / La Florida', 'casa', 'venta', 'La Florida', '', 180000000, 'CLP', NULL, 3, 2, 1, 0, 189, 189, 189, NULL, '', 0, NULL, '[]', 'Se vende acogedora y amplia propiedad ubicada en un condominio tranquilo y de ambiente familiar en La Florida.', '["Se vende acogedora y amplia propiedad ubicada en un condominio tranquilo y de ambiente familiar en La Florida. Emplazada en calle Ciprés Cordillerano, entre Rojas de Magallanes y Del Prado, cuenta con una excelente conectividad y rápida accesibilidad a transporte público, además de estar a pasos de Patio Outlet La Florida, supermercados, parques, farmacias y comercio local.\nLa casa se encuentra en excelente estado de conservación y destaca por su luminosidad y distribución de espacios.\nCaracterísticas principales:\nSuperficie: 189 m² de terreno | 73 m² construidos aprox.\nLiving-comedor: Espacioso y confortable, ideal para compartir en familia.\nCocina: Amplia, independiente (cerrada) y con salida directa al patio posterior.\nDormitorios: 3 amplios dormitorios con piso flotante. El principal es en suite y cuenta con acceso privado al patio.\nBaños: 2 baños completos (uno de ellos con ventilación natural).\nEstacionamiento: Capacidad para 2 vehículos pequeños (ancho de acceso: 2 metros).\nExteriores y terminaciones: Gran patio trasero y piso cerámico en áreas comunes.\nInformación adicional:\nContribuciones: $42.000 aprox. por cuota.\n¡Excelente oportunidad para vivir en un sector consolidado y residencial! Coordine su visita."]', '["Residencial", "Condominio", "Áreas Verdes", "Áreas Libres", "Accesibilidad", "Buena Conectividad", "Comercio Cercano"]', 0, '2026-11-12', 'PUBLICADA', 131, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201541-los-ciruelos-orientes-ovalle', 'Los Ciruelos Orientes / Ovalle', 'casa', 'venta', 'Ovalle', '', 7500, 'UF', NULL, 4, 3, 0, 0, 106, 106, 398, NULL, '', 0, NULL, '[]', 'Hermosa casa en consolidado sector residencial de Ovalle', '["Hermosa casa en consolidado sector residencial de Ovalle\nSe vende excelente propiedad emplazada en uno de los barrios residenciales más destacados y tranquilos de la ciudad de Ovalle. Destaca por su entorno familiar, gran conectividad y cercanía a colegios, supermercados y estaciones de servicio.\nDistribución y Características:\nÁrea social: Amplio living-comedor con excelente iluminación natural.\nCocina y Servicios: Cocina funcional con logia independiente y bodega de almacenamiento.\nDormitorios: 4 dormitorios espaciosos (principal en suite).\nBaños: 3 baños completos.\nExterior: Confortable terraza techada, ideal para el descanso y reuniones familiares.\nSeguridad y Equipamiento:\nPortón eléctrico.\nCitófono con cámara de vigilancia integrada.\nUbicada frente o a pasos de plazas con juegos infantiles.\nUna propiedad perfecta para quienes buscan calidad de vida, seguridad y comodidad en Ovalle."]', '["Residencial", "Logia", "Bodega", "Terraza", "Áreas Verdes", "Buena Conectividad", "Comercio Cercano", "Colegio Cercano", "Seguridad"]', 0, '2026-11-12', 'PUBLICADA', 147, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201543-los-jacaranda-ovalle', 'Los Jacaranda / Ovalle', 'casa', 'venta', 'Ovalle', '', 240000000, 'CLP', NULL, 3, 3, 1, 0, 93, 93, 221, NULL, '', 0, NULL, '[]', 'SE VENDE | Exclusiva Casa Aislada en Barrio Las Acacias, Ovalle', '["SE VENDE | Exclusiva Casa Aislada en Barrio Las Acacias, Ovalle\nPrecio: $240.000.000\nSe vende hermosa casa de dos pisos, completamente individual y aislada, ubicada en el prestigioso Barrio Residencial Las Acacias. Un sector altamente cotizado en Ovalle por su tranquilidad, seguridad y entorno consolidado. Posee una ubicación privilegiada a pasos del Supermercado Santa Isabel, Stripcenter, farmacias y los reconocidos colegios Tamelcura y Amalia Errázuriz, además de contar con excelente conectividad a solo 5 minutos del centro de la ciudad.\nSuperficie:\nTerreno: 221 m²\nConstrucción: 93 m²\nDistribución y Equipamiento:\nPrimer Nivel: Hall de acceso, acogedor living-comedor, cocina totalmente amoblada y equipada (horno empotrado, encimera y campana), baño de visitas y logia independiente.\nDormitorios: 3 espaciosos dormitorios (principal en suite).\nBaños: 3 baños en total.\nExteriores: Amplio patio con áreas verdes consolidadas y espacio para terraza.\nEspacios Adicionales: Taller/bodega de gran tamaño más un segundo taller independiente, ideal para proyectos personales, arte o manualidades.\nUna propiedad única por su terreno, versatilidad y ubicación estratégica.\nContáctenos para coordinar su visita."]', '["Residencial", "Logia", "Bodega", "Terraza", "Áreas Verdes", "Buena Conectividad", "Comercio Cercano", "Colegio Cercano", "Seguridad"]', 0, '2026-11-12', 'PUBLICADA', 149, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201545-pedro-barrios-ovalle', 'Pedro Barrios / Ovalle', 'casa', 'venta', 'Ovalle', '', 5900, 'UF', NULL, 3, 3, 1, 0, 127, 127, 235, NULL, '', 0, NULL, '[]', 'Exclusiva casa de hormigón armado en Barrio Hacienda Mirador, Ovalle', '["Exclusiva casa de hormigón armado en Barrio Hacienda Mirador, Ovalle\nSe vende sólida casa de dos pisos, completamente aislada e individual, construida en hormigón armado y ubicada en el consolidado Barrio Residencial Hacienda Mirador. Un sector altamente cotizado por su entorno tranquilo y excelente conectividad, a pasos de Supermercado Santa Isabel, Stripcenter, farmacias y prestigiosos colegios como Tamelcura y Amalia Errázuriz, además de estar a solo 5 minutos del centro de Ovalle.\nSuperficie:\nTerreno: 235 m²\nConstrucción: 127.88 m²\nDistribución Interior:\nPrimer Nivel: Hall de acceso, amplio living-comedor, baño de visitas y cocina independiente totalmente amoblada y equipada (horno empotrado, encimera y campana).\nSegundo Nivel / Área Privada: 3 dormitorios (principal en suite) y un cómodo family room (sala de estar/TV).\nBaños: 3 baños en total (incluye el de visitas).\nExteriores y Equipamiento:\nEstacionamiento: Capacidad para 2 a 3 vehículos con elegante techumbre de vigas a la vista y teja chilena.\nExteriores: Amplio patio con áreas verdes consolidadas, sector de terraza, taller/bodega versátil y portón eléctrico.\nServicios: Logia exterior con cobertizo y sistema de agua caliente mediante calefón.\nUna propiedad de construcción sólida, excelente metraje y finas terminaciones."]', '["Residencial", "Logia", "Bodega", "Terraza", "Áreas Verdes", "Buena Conectividad", "Comercio Cercano", "Colegio Cercano"]', 0, '2026-11-12', 'PUBLICADA', 151, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201604-galvarino-gallardo-providencia', 'Galvarino Gallardo / Providencia', 'departamento', 'venta', 'Providencia', '', 11300, 'UF', NULL, 3, 2, 1, 0, 99, 99, NULL, NULL, '', 0, NULL, '[]', '¡No dejes pasar la oportunidad de adquirir este espectacular departamento en venta en Providencia!', '["¡No dejes pasar la oportunidad de adquirir este espectacular departamento en venta en Providencia! Con una ubicación privilegiada en Galvarino Gallardo, esta propiedad cuenta con 3 amplios dormitorios, 2 baños, y una superficie total de 99 m2.\nDisfruta de una orientación al norte que asegura una excelente luminosidad durante todo el día. Además, su sistema de calefacción de aire caliente y aire acondicionado te garantizará el confort que buscas en cualquier época del año.\nEste departamento es ideal para familias que deseen vivir en un entorno tranquilo y seguro, cercano a parques, colegios, comercios y con excelente conectividad. No pierdas la oportunidad de hacer tuya esta propiedad por solo UF 11300. ¡Contáctanos para más información y agenda una visita!"]', '["Áreas Verdes", "Áreas Libres", "Buena Conectividad", "Colegio Cercano", "Aire Acondicionado", "Calefacción"]', 0, '2026-11-12', 'PUBLICADA', 210, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201700-jose-arrieta-penalolen', 'Jose Arrieta / Peñalolen', 'departamento', 'venta', 'Peñalolén', '', 9785, 'UF', NULL, 3, 3, 2, 0, 101, 152, NULL, NULL, '', 0, NULL, '[]', 'Tu nuevo hogar con vista panorámica en el límite de La Reina Alta y Peñalolén', '["Tu nuevo hogar con vista panorámica en el límite de La Reina Alta y Peñalolén\nImagina despertar cada día con una vista privilegiada a la ciudad y disfrutar de atardeceres inolvidables desde tu terraza privada con quincho. Un departamento diseñado para brindar amplitud, confort y elegancia en un entorno natural y seguro.\nDistribución y finas terminaciones:\nRecibidor: Elegante hall de acceso con puerta vidriada.\nÁrea social: Amplio living-comedor con salida directa a la terraza.\nCocina gourmet: Full eléctrica, equipada con isla central y cubiertas de granito.\nDormitorios: Suite principal con baño privado y doble vanitorio. Más 2 dormitorios amplios con closet.\nBaños: 3 en total (incluye suite principal).\nTerraza: Incluye quincho equipado y malla de seguridad instalada.\nEquipamiento: Calefacción central, ventanas de termopanel y sistema de alarma integrado.\nAtributos y áreas comunes del condominio:\nAmplias áreas verdes y senderos para caminatas, mascotas o bicicleta.\nPiscina al aire libre (adultos y niños) y juegos infantiles.\nSalón de eventos equipado con terraza y quincho.\nGimnasio equipado, lavandería y conserjería con seguridad 24/7 y cámaras de vigilancia.\nIncluye: 2 estacionamientos subterráneos y 1 bodega.\nUbicación estratégica:\nA pasos de la Universidad Adolfo Ibáñez, Templo Bahá''í, Hospital Militar, colegios de excelencia, supermercados y áreas verdes.\n¡Agenda tu visita hoy y descubre la calidad de vida que mereces!"]', '["Condominio", "Amoblado", "Bodega", "Piscina", "Terraza", "Quincho", "Áreas Verdes", "Gimnasio", "Comercio Cercano", "Centros de Salud", "Colegio Cercano", "Universidad Cercana", "Seguridad", "Calefacción"]', 0, '2026-11-12', 'PUBLICADA', 306, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201704-vicuna-mackenna-metro-rodrigo-de-araya', 'Vicuña Mackenna / Metro Rodrigo de Araya', 'departamento', 'venta', 'San Joaquín', '', 2686, 'UF', NULL, 2, 2, 0, 0, 46, 51, NULL, NULL, '', 0, NULL, '[]', '¡Gran oportunidad de inversión o para vivir en San Joaquín!', '["¡Gran oportunidad de inversión o para vivir en San Joaquín!\nUbicado estratégicamente sobre Av. Vicuña Mackenna, justo frente a la estación de Metro Rodrigo de Araya, este departamento destaca por su conectividad imbatible y excelente distribución.\nDetalles de la propiedad:\nPrecio: UF 2.786\nSuperficie: 46 m² eficientes e iluminados.\nDistribución: 2 dormitorios amplios (ideales para home office, niños o visitas) y 2 baños completos.\nEntorno: Paso a paso de metro, transporte público, supermercados y servicios claves.\nUn formato muy atractivo tanto para habitárselo como para generar alta rentabilidad de arriendo.\n¿Te gustaría agendar una visita o recibir más información? ¡Escríbeme hoy y lo coordinamos!"]', '["Buena Conectividad", "Comercio Cercano"]', 0, '2026-11-12', 'PUBLICADA', 310, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201540-irma-alcayaga-cortes-ovalle', 'Irma Alcayaga Cortes / Ovalle', 'casa', 'venta', 'Ovalle', '', 7500, 'UF', NULL, 4, 4, 2, 0, 120, 120, 158, NULL, '', 0, NULL, '[]', 'Se vende espectacular casa de dos pisos, recientemente remodelada con finas terminaciones y excelente distribución de espacios.', '["Se vende espectacular casa de dos pisos, recientemente remodelada con finas terminaciones y excelente distribución de espacios. Ubicada en uno de los sectores residenciales más consolidados y de mayor plusvalía de la ciudad.\nSuperficie:\nConstruidos: 120 m² (casa) + 38 m² (quincho).\nDistribución y Equipamiento:\nDormitorios: 4 amplios dormitorios (2 de ellos en suite).\nBaños: 3 baños completos + 1 baño de visitas\nÁrea Social: Acogedor living-comedor independiente con aire acondicionado.\nEspacios comunes: Cómodo family room, ideal para sala de estar o TV.\nCocina y Servicios: Cocina independiente, logia separada y patio de servicio equipado con bodegas integradas.\nQuincho: Espectacular quincho cerrado/techado de 38 m², perfecto para reuniones familiares y eventos.\nTerminaciones y Adicionales:\nVentanales con termopanel (aislación térmica y acústica).\nConexión a Red de Gas Natural\nEstacionamiento para 2 vehículos con portón eléctrico.\n¡Una propiedad lista para habitar, que combina comodidad, seguridad y una ubicación privilegiada!\nContáctenos para coordinar su visita."]', '["Residencial", "Amoblado", "Logia", "Bodega", "Quincho", "Áreas Verdes", "Seguridad", "Aire Acondicionado"]', 0, '2026-11-12', 'PUBLICADA', 146, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('201760-proyecto-eco-estacion', 'Proyecto Eco Estación (Entrega Inmediata) . Bono Pie 20%', 'departamento', 'venta', 'Estación Central', '', 1868, 'UF', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, '', 0, NULL, '["Varias tipologías"]', 'Eco Estación: Tu próximo espacio o inversión en Estación Central', '["Eco Estación: Tu próximo espacio o inversión en Estación Central\nEco Estación redefine el estilo de vida urbano en Santiago. Este proyecto de 30 pisos combina ubicación estratégica, diseño contemporáneo y alta rentabilidad, consolidándose como una propuesta única para vivir o invertir en la Región Metropolitana.\nUbicado a pasos de la Alameda y del Metro San Alberto Hurtado, el edificio garantiza conectividad inmediata a vías principales, comercio, servicios y universidades como la USACH.\nSus departamentos destacan por los conceptos Espacios Más y Diseño Más, integrando cocinas autoría de reconocidos diseñadores chilenos, terminaciones de alto estándar y amplios ventanales que optimizan la luz natural.\nGracias a sus precios competitivos por m² y a la constante demanda de arriendo en la zona, Eco Estación asegura una atractiva plusvalía y retorno de inversión.\nConoce nuestras unidades disponibles y agenda tu visita hoy.\nTipologias:\n1.-Home Studio\n2.-1 dormitorio\n3.-2 dormitorios\nCondiciones comerciales:\nBono pie: Hasta 20% (puedes comprar sin pagar pie)\nArriendo Garantizado: 2 años"]', '["Logia", "Buena Conectividad", "Universidad Cercana"]', 0, '2026-11-12', 'PUBLICADA', 366, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202036-hermosa-casa-sector-del-sol-quilpue', 'Hermosa Casa / Sector del Sol / Quilpue', 'casa', 'venta', 'Quilpué', '', 294000000, 'CLP', NULL, 4, 2, 1, 0, 136, 136, 384, NULL, '', 0, NULL, '[]', 'Se vende acogedora propiedad de dos pisos, emplazada en un sector residencial con excelente conectividad y alta plusvalía en la comuna de Quilpué.', '["Se vende acogedora propiedad de dos pisos, emplazada en un sector residencial con excelente conectividad y alta plusvalía en la comuna de Quilpué.\nEn el primer piso, la casa cuenta con un cómodo living-comedor equipado con chimenea, cocina tradicional, un dormitorio y un baño de visitas. Destaca una sala de estar o terraza cerrada muy luminosa, que también incluye chimenea, ideal para disfrutar en familia.\nEl segundo piso dispone de un amplio hall de distribución que conecta con tres espaciosos dormitorios (todos con clóset), un baño completo y una habitación adicional versátil que puede funcionar como bodega, escritorio o cuarto dormitorio.\nEn el exterior, la propiedad posee dos bodegas y una habitación independiente con baño, perfecta para ser habilitada como dormitorio de servicio o para alojados.\nEl estacionamiento cuenta con un garaje con capacidad para dos vehículos y espacio adicional para otros cuatro autos aproximadamente en el exterior.\nUbicación privilegiada: Cercana a locomoción colectiva, estación de metro El Sol, y a solo minutos del centro comercial El Belloto, colegios y el centro de la ciudad."]', '["Residencial", "Amoblado", "Bodega", "Terraza", "Áreas Verdes", "Buena Conectividad", "Colegio Cercano"]', 0, '2026-11-12', 'PUBLICADA', 642, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202038-casa-residencial-vina-del-mar', 'Casa Residencial / Viña del Mar', 'casa', 'venta', 'Viña del Mar', '', 9990, 'UF', NULL, 5, 5, 2, 0, 210, 210, 220, NULL, '', 0, NULL, '[]', 'Descubre esta encantadora propiedad que combina carácter, amplitud y funcionalidad en una ubicación privilegiada.', '["Descubre esta encantadora propiedad que combina carácter, amplitud y funcionalidad en una ubicación privilegiada. Con cinco dormitorios (tres en suite) y cuatro baños, es el hogar perfecto para la vida familiar y el teletrabajo.\nEl área social destaca por un luminoso living-comedor con chimenea, ideal para mañanas y noches acogedoras. La cocina viene completamente amoblada y equipada con encimera y campana. Para mayor practicidad, la propiedad incluye logia, dos bodegas y un espacio de servicio con baño independiente, perfecto como departamento de invitados.\nEn el nivel superior se encuentra una espaciosa mansarda con baño completo: un ambiente versátil que regala una hermosa vista panorámica a la bahía. En el exterior, un acogedor patio invita a relajarse al aire libre, complementado con dos estacionamientos cerrados.\nUbicada en Recreo, uno de los sectores residenciales más tradicionales y tranquilos de Viña del Mar, la propiedad ofrece una conectividad excelente, áreas verdes y cercanía a colegios, universidades y comercio."]', '["Residencial", "Logia", "Bodega", "Áreas Verdes", "Buena Conectividad", "Colegio Cercano", "Universidad Cercana"]', 0, '2026-11-12', 'PUBLICADA', 644, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202039-departamento-con-con', 'Departamento / Valparaiso', 'departamento', 'venta', 'Valparaíso', '', 1800, 'UF', NULL, 2, 1, 0, 0, 46, 46, NULL, NULL, '', 0, NULL, '[]', 'Hermoso y cómodo departamento en Bosque Los Ingleses, Valparaíso', '["Hermoso y cómodo departamento en Bosque Los Ingleses, Valparaíso\nUbicado en un barrio muy tranquilo y residencial, con excelente conectividad: a pasos del Hospital Eduardo Pereira, supermercado Santa Isabel y locomoción colectiva. A solo minutos de Av. Argentina y del centro de la ciudad.\nCaracterísticas de la propiedad:\n2 dormitorios amplios\n1 baño completo\nCocina americana equipada\nBalcón con excelente vista panorámica\nEquipamiento del condominio:\nConserjería y seguridad 24/7\nLavandería\nGimnasio\nSala multipropósito"]', '["Residencial", "Condominio", "Cocina Americana", "Balcón", "Gimnasio", "Buena Conectividad", "Comercio Cercano", "Centros de Salud", "Seguridad"]', 0, '2026-11-12', 'PUBLICADA', 645, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202040-hermosa-casa-pena-blanca', 'Hermosa Casa / Peña Blanca', 'casa', 'venta', 'Villa Alemana', '', 138000000, 'CLP', NULL, 3, 3, 3, 0, 80, 80, 200, NULL, '', 0, NULL, '[]', 'Hermosa casa independiente en condominio sin gastos comunes – Peña Blanca, Villa Alemana', '["Hermosa casa independiente en condominio sin gastos comunes – Peña Blanca, Villa Alemana\nExcelente oportunidad de compra en un entorno tranquilo y seguro, ubicada en Avenida Las Palmas, sector Peña Blanca. Destaca por su estratégica conectividad y rápido acceso al empalme con el Troncal Sur, facilitando el traslado hacia el resto de la región.\nDistribución y características:\nSuperficie: 80 m² construidos | 200 m² de terreno total.\nHall de entrada independiente.\nLiving-comedor amplio y luminoso.\n3 dormitorios (dormitorio principal en primer piso para mayor comodidad).\n3 baños en total.\nCocina completamente amoblada.\nExterior y adicionales:\nAmplio patio con pérgola ideal para compartir.\nEstacionamiento con capacidad para 3 vehículos.\nPropiedad independiente dentro de condominio.\nSin pago de gastos comunes (exenta de GGCC)."]', '["Condominio", "Áreas Verdes", "Buena Conectividad"]', 0, '2026-11-12', 'PUBLICADA', 646, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202043-hermosa-casa-teniente-serrano-quilpue', 'Hermosa Casa / Teniente Serrano / Quilpue', 'casa', 'venta', 'Quilpué', '', 270000000, 'CLP', NULL, 4, 3, 2, 0, 135, 135, 511, NULL, '', 0, NULL, '[]', 'Amplia e impecable propiedad con gran terreno y piscina – Sector Teniente Serrano, Quilpué', '["Amplia e impecable propiedad con gran terreno y piscina – Sector Teniente Serrano, Quilpué\nUbicada en el tranquilo y residencial sector de Teniente Serrano, esta propiedad destaca por sus amplios espacios interiores y su extenso terreno. Emplazada en un entorno acogedor a solo minutos del centro de Quilpué, cuenta con excelente conectividad hacia el Troncal Sur y Camino Orozco, facilitando un rápido desplazamiento hacia Viña del Mar, Valparaíso y Santiago.\nSuperficie:\nConstruidos: 135 m²\nTerreno total: 511 m²\nDistribución y características interiores:\n4 dormitorios amplios, todos equipados con closet.\n3 baños completos.\nLiving y comedor independientes, ideales para separar ambientes.\nCocina amoblada de gran tamaño y excelente capacidad de almacenamiento.\nLogia funcional e independiente.\nExterior y esparcimiento:\nAmplio patio consolidado con piscina, perfecto para el descanso y la vida familiar."]', '["Residencial", "Amoblado", "Logia", "Piscina", "Áreas Verdes", "Buena Conectividad"]', 1, '2026-11-12', 'PUBLICADA', 649, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202053-departamento-los-pinos-quilpue', 'Departamento / Los Pinos Quilpué', 'departamento', 'venta', 'Quilpué', '', 93000000, 'CLP', NULL, 3, 2, 1, 0, 68, 68, NULL, NULL, '', 0, NULL, '[]', '¡Excelente oportunidad en Quilpué!', '["¡Excelente oportunidad en Quilpué! Se vende amplio y luminoso departamento con orientación norte, ubicado en un cuarto piso del consolidado Condominio Alto Los Pinos I. Emplazado en un entorno tranquilo y seguro, con gran conectividad, cercano a colegios, supermercados y locomoción colectiva.\nCaracterísticas del departamento:\nDormitorios: 3 amplios dormitorios, todos con closet.\nBaños: 2 baños completos.\nEspacios comunes: Espacioso living-comedor con excelente iluminación natural.\nExteriores: 2 terrazas independientes y orientación norte (muy soleado durante todo el día).\nCocina: Amoblada y equipada con logia independiente.\nEstacionamiento: 1 espacio privado de estacionamiento.\nAtributos del condominio:\nAcceso controlado con conserjería 24/7.\nClub house para eventos.\nÁreas verdes y juegos infantiles."]', '["Condominio", "Logia", "Terraza", "Áreas Verdes", "Buena Conectividad", "Comercio Cercano", "Colegio Cercano", "Seguridad"]', 1, '2026-11-12', 'PUBLICADA', 659, 'dia');
INSERT OR IGNORE INTO propiedades (slug, titulo, tipo, operacion, comuna, sector, precio_valor, precio_moneda, precio_periodo, dormitorios, banos, estacionamientos, bodegas, superficie_util, superficie_total, terreno, piso, orientacion, anio, gastos_comunes, etiquetas, resumen, descripcion, caracteristicas, destacada, publicada, estado, ilustracion_seed, ilustracion_tono) VALUES ('202057-departamento-mesa-de-aragon-vina', 'Departamento / Mesa de Aragón / Viña', 'departamento', 'venta', 'Viña del Mar', '', 142000000, 'CLP', NULL, 3, 2, 1, 0, 79, 79, NULL, NULL, '', 0, NULL, '[]', 'Se vende impecable departamento en tercer piso, ubicado en el consolidado Condominio Mesas de Aragón, en el sector de Gómez Carreño.', '["Se vende impecable departamento en tercer piso, ubicado en el consolidado Condominio Mesas de Aragón, en el sector de Gómez Carreño. Una propiedad destacar por su amplitud, excelente distribución y conectividad, cercana a comercio local y locomoción colectiva.\nCaracterísticas Principales:\nSuperficie: 78,59 m² totales construidos.\nDormitorios: 3 amplios dormitorios.\nBaños: 2 baños completos.\nÁrea Social: Espacioso living-comedor con gran iluminación natural.\nExterior: Terraza privada.\nEquipamiento del Condominio:\nAcceso controlado y seguridad en condominio cerrado.\nPiscina.\nHermosas áreas verdes y zonas comunes.\nValor de Venta: $142.000.000 + honorarios de corretaje."]', '["Condominio", "Piscina", "Terraza", "Áreas Verdes", "Buena Conectividad", "Seguridad"]', 1, '2026-11-12', 'PUBLICADA', 663, 'dia');
